const d=100;function G(t){return t*100}function L(t){return t/100}function O(t){return t.toFixed(4)}const S=85,X=37;function Y(t){return Math.max(Math.abs(t.x),Math.abs(t.z))||1}const o=Math.PI/180;function Z(t,I,C,T){const E=Math.abs(t.x)/2,l=Math.abs(t.y)/2,R=Math.abs(t.z)/2,c=-I*o%(2*Math.PI),M=-C*o%(2*Math.PI),h=-T*o%(2*Math.PI),e=Math.cos(c),r=Math.sin(c),x=Math.cos(M),f=Math.sin(M),u=Math.cos(h),i=Math.sin(h);let s=0,a=0,n=0;for(const U of[-1,1])for(const F of[-1,1])for(const N of[-1,1]){let m=U*E,z=F*l,b=N*R;const P=z*e-b*r,_=z*r+b*e,y=m*x+_*f,p=-m*f+_*x,A=y*u-P*i,D=y*i+P*u;s=Math.max(s,Math.abs(A)),a=Math.max(a,Math.abs(D)),n=Math.max(n,Math.abs(p))}return{x:s*2,y:a*2,z:n*2}}function g(t){return Math.round(t*1e4)/1e4+""}export{X as C,S as P,g as a,Y as b,L as c,Z as d,d as e,O as f,G as u};
